export const searchPlaces = async (
  q: string,
  lat?: number,
  lng?: number,
  locationBias?: string,
  options?: RequestInit,
): Promise<PlaceResult[]> => {
  const params = new URLSearchParams({ q });
  if (lat != null) params.set("lat", String(lat));
  if (lng != null) params.set("lng", String(lng));
  if (locationBias?.trim()) params.set("locationBias", locationBias.trim());
  return customFetch<PlaceResult[]>(`/api/places/search?${params}`, {
    ...options,
    method: "GET",
  });
};

