// ─── Places / Discover ────────────────────────────────────────────────────────

export const getDiscoverPlacesUrl = () => `/api/places/discover`;

export const discoverPlaces = async (params: DiscoverPlacesRequest, options?: RequestInit): Promise<DiscoverPlaceResult[]> => {
  const query = new URLSearchParams();
  if (params.cuisines?.length) query.set('cuisines', params.cuisines.join(','));
  if (params.radius != null) query.set('radius', String(params.radius));
  if (params.lat != null) query.set('lat', String(params.lat));
  if (params.lng != null) query.set('lng', String(params.lng));
  if (params.zip) query.set('zip', params.zip);
  return customFetch<DiscoverPlaceResult[]>(`${getDiscoverPlacesUrl()}?${query}`, { ...options, method: 'GET' });
};

export const getDiscoverPlacesQueryKey = (params: DiscoverPlacesRequest) =>
  [`/api/places/discover`, params] as const;

export const getDiscoverPlacesQueryOptions = <TData = Awaited<ReturnType<typeof discoverPlaces>>, TError = ErrorType<void>>(
  params: DiscoverPlacesRequest,
  options?: { query?: UseQueryOptions<Awaited<ReturnType<typeof discoverPlaces>>, TError, TData>, request?: SecondParameter<typeof customFetch> }
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};
  const queryKey = queryOptions?.queryKey ?? getDiscoverPlacesQueryKey(params);
  const queryFn: QueryFunction<Awaited<ReturnType<typeof discoverPlaces>>> = ({ signal }) =>
    discoverPlaces(params, { signal, ...requestOptions });
  return { queryKey, queryFn, enabled: false, ...queryOptions } as UseQueryOptions<Awaited<ReturnType<typeof discoverPlaces>>, TError, TData> & { queryKey: QueryKey };
};

export type DiscoverPlacesQueryResult = NonNullable<Awaited<ReturnType<typeof discoverPlaces>>>;
export type DiscoverPlacesQueryError = ErrorType<void>;

