// ─── Pre-signed photo upload (receipt + gallery) ──────────────────────────────
// Two-step flow: call upload-url to get a signed PUT URL, PUT the binary
// directly from the device to GCS (bypassing the proxy entirely), then call
// confirm to create the DB record and receive a signed read URL.

export interface PhotoUploadUrlResponse {
  uploadUrl: string;
  objectPath: string;
  /** Short-lived HMAC-signed token — pass verbatim to the confirm endpoint. */
  token: string;
}

// Receipt photos (host only)
export const getRequestReceiptPhotoUploadUrlUrl = (eventId: number) => `/api/events/${eventId}/receipt/photos/upload-url`;

export const requestReceiptPhotoUploadUrl = async (eventId: number, mimeType: string, options?: RequestInit): Promise<PhotoUploadUrlResponse> =>
  customFetch<PhotoUploadUrlResponse>(getRequestReceiptPhotoUploadUrlUrl(eventId), {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(options?.headers ?? {}) },
    body: JSON.stringify({ mimeType }),
  });

export const getConfirmReceiptPhotoUploadUrl = (eventId: number) => `/api/events/${eventId}/receipt/photos/confirm`;

export const confirmReceiptPhotoUpload = async (eventId: number, token: string, options?: RequestInit): Promise<ReceiptPhotoItem> =>
  customFetch<ReceiptPhotoItem>(getConfirmReceiptPhotoUploadUrl(eventId), {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(options?.headers ?? {}) },
    body: JSON.stringify({ token }),
  });

